mapper.insert:
INSERT INTO REGION (
    region_id,
    region_name,
    parent_region_id
) VALUES (
    #{regionId},
    #{regionName},
    #{parentRegionId}
)
ON DUPLICATE KEY UPDATE
    region_name = VALUES(region_name),
    parent_region_id = VALUES(parent_region_id);

INSERT INTO PLACE_IMAGE (
    place_id,
    image_url,
    sort_order
) VALUES (
    #{placeId},
    #{imageUrl},
    #{sortOrder}
);
